import { useEffect, useState } from "react";
import {
  fetchLoggedUser,
  fetchUserRepos,
  fetchCommits,
  uploadFile,
  fetchPRHeatmap,
  fetchMergeHeatmap,
} from "./api/githubApi";

import { fetchTimeline } from "./api/jiraApi";

import Heatmap from "./components/Heatmap";
import MonthYearPicker from "./components/MonthYearPicker";
import TimelineViewer from "./components/TimelineViewer";

function App() {
  // ---------------- STATES ----------------
  const [darkMode, setDarkMode] = useState(true);
  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");

  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  const [commitHeatmap, setCommitHeatmap] = useState({});
  const [prHeatmap, setPrHeatmap] = useState({});
  const [mergeHeatmap, setMergeHeatmap] = useState({});

  const [jiraKey, setJiraKey] = useState("");
  const [timeline, setTimeline] = useState(null);

  const [selectedFile, setSelectedFile] = useState(null);

  const [actionType, setActionType] = useState("commits");
  const [userCreatedAt, setUserCreatedAt] = useState(null);

  // ---------------- FULL-SCREEN DARK MODE ----------------
  useEffect(() => {
    document.body.style.backgroundColor = darkMode ? "#020617" : "#F8FAFC";
    document.body.style.color = darkMode ? "#E5E7EB" : "#020617";
  }, [darkMode]);

  // ---------------- LOAD TOKEN ----------------
  useEffect(() => {
    const token = new URLSearchParams(window.location.search).get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  // ---------------- LOAD USER + REPOS ----------------
  useEffect(() => {
    if (!localStorage.getItem("token")) return;

    fetchLoggedUser().then((res) => {
      setOwner(res.data.login);
      setUserCreatedAt(res.data.created_at);
    });

    fetchUserRepos().then((res) => {
      setRepos(res.data);
      if (res.data.length > 0) setSelectedRepo(res.data[0].name);
    });
  }, []);

  // ---------------- HEATMAP HANDLERS ----------------
  const buildCommitHeatmap = async (payload) => {
    const res = await fetchCommits(payload);

    const map = {};
    res.data.forEach((c) => {
      const date = c.commit.committer.date.substring(0, 10);
      map[date] = (map[date] || 0) + 1;
    });

    setCommitHeatmap(map);
  };

  const buildPRHeatmap = async (payload) => {
    const res = await fetchPRHeatmap(payload);
    setPrHeatmap(res.data);
  };

  const buildMergeHeatmap = async (payload) => {
    const res = await fetchMergeHeatmap(payload);
    setMergeHeatmap(res.data);
  };

  // ---------------- ANALYZE BUTTON ----------------
  const fetchData = async () => {
    if (!owner || !selectedRepo) return alert("Select repository first");

    const payload = { owner, repo: selectedRepo, startDate, endDate };

    if (actionType === "commits") await buildCommitHeatmap(payload);
    if (actionType === "prs") await buildPRHeatmap(payload);
    if (actionType === "merge") await buildMergeHeatmap(payload);

    if (actionType === "clone") {
      window.open(`https://github.com/${owner}/${selectedRepo}.git`, "_blank");
    }
  };

  // ---------------- UPLOAD FILE ----------------
  const handleUpload = async () => {
    if (!selectedFile) return alert("Select a file first");

    const reader = new FileReader();

    reader.onload = async () => {
      await uploadFile({
        owner,
        repo: selectedRepo,
        path: "uploads/" + selectedFile.name,
        message: "Uploaded from dashboard",
        content: reader.result.split(",")[1],
      });

      alert("Uploaded Successfully");
    };

    reader.readAsDataURL(selectedFile);
  };

  // ---------------- LOAD JIRA TIMELINE ----------------
  const loadTimeline = async () => {
    if (!jiraKey) return alert("Enter Jira Issue Key");

    try {
      const res = await fetchTimeline({ key: jiraKey });
      setTimeline(res.data);
    } catch (e) {
      alert("Failed to fetch Jira timeline");
    }
  };

  // ---------------- RENDER ----------------
  const heatmapData =
    actionType === "commits"
      ? commitHeatmap
      : actionType === "prs"
      ? prHeatmap
      : mergeHeatmap;

  return (
    <div style={styles.container}>
      {/* ---------------- TOP NAV ---------------- */}
      <div style={styles.topBar}>
        <h2>🚀 GitHub Analytics + Jira Timeline</h2>

        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={() => setDarkMode(!darkMode)}>
            {darkMode ? "☀ Light Mode" : "🌙 Dark Mode"}
          </button>

          <button
            onClick={() =>
              window.open(`https://github.com/${owner}/${selectedRepo}.git`)
            }
          >
            ⬇ Clone Repo
          </button>

          <button onClick={handleUpload}>⬆ Upload</button>
          <input
            type="file"
            onChange={(e) => setSelectedFile(e.target.files[0])}
          />
        </div>
      </div>

      {/* ---------------- LOGIN ---------------- */}
      {!owner && (
        <button
          style={styles.loginBtn}
          onClick={() =>
            (window.location.href = "http://localhost:8080/auth/github")
          }
        >
          Login with GitHub
        </button>
      )}

      {/* ---------------- AFTER LOGIN ---------------- */}
      {owner && (
        <>
          {/* ----------- Repo + Dates + Action Selector ----------- */}
          <div style={styles.form}>
            <select onChange={(e) => setSelectedRepo(e.target.value)}>
              {repos.map((r) => (
                <option key={r.id} value={r.name}>
                  {r.name}
                </option>
              ))}
            </select>

            <MonthYearPicker
              userCreatedAt={userCreatedAt}
              onChange={({ startDate, endDate }) => {
                setStartDate(startDate);
                setEndDate(endDate);
              }}
            />

            <select onChange={(e) => setActionType(e.target.value)}>
              <option value="commits">Commits</option>
              <option value="prs">Pull Requests</option>
              <option value="merge">Merged PRs</option>
              <option value="clone">Clone Repo</option>
            </select>

            <button onClick={fetchData}>Analyze</button>
          </div>

          {/* ---------------- HEATMAP ---------------- */}
          <div style={styles.heatmapBox}>
            <h3>🔥 Activity Heatmap</h3>
            <Heatmap data={heatmapData} />
          </div>

          {/* ---------------- JIRA TIMELINE INPUT ---------------- */}
          <div style={styles.timelineForm}>
            <input
              type="text"
              placeholder="Enter Jira Key (EX: SAM-23)"
              value={jiraKey}
              onChange={(e) => setJiraKey(e.target.value)}
            />
            <button onClick={loadTimeline}>Load Timeline</button>
          </div>

          {/* ---------------- TIMELINE VIEWER ---------------- */}
          <TimelineViewer timeline={timeline} />
        </>
      )}
    </div>
  );
}

// ---------------- STYLES ----------------
const styles = {
  container: { minHeight: "100vh", padding: 20, fontFamily: "Arial" },

  topBar: {
    display: "flex",
    justifyContent: "space-between",
    padding: "10px 20px",
    marginBottom: 20,
    background: "rgba(255,255,255,0.07)",
    borderRadius: 12,
    backdropFilter: "blur(6px)",
  },

  loginBtn: {
    padding: 10,
    marginTop: 20,
    fontSize: 18,
  },

  form: {
    display: "flex",
    gap: 10,
    justifyContent: "center",
    marginTop: 20,
  },

  heatmapBox: {
    width: "75%",
    margin: "30px auto",
    padding: 20,
    background: "rgba(255,255,255,0.06)",
    borderRadius: 12,
    backdropFilter: "blur(6px)",
  },

  timelineForm: {
    display: "flex",
    gap: 10,
    justifyContent: "center",
    marginTop: 30,
  },
};

export default App;
